selector_to_html = {"a[href=\"multi-backend-prebuilt-docker-image-install/install-metax.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab MetaX\uff08\u6c90\u66e6\u80a1\u4efd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/metax/\">metax</a>3.6<a class=\"headerlink\" href=\"#metax-metax3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (C550)<a class=\"headerlink\" href=\"#use-the-image-c550\" title=\"Link to this heading\">#</a></h3>", "a[href=\"flagtree-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Enable FlagTree CPU on Arm64<a class=\"headerlink\" href=\"#enable-flagtree-cpu-on-arm64\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/flagtree-cpu/tree/triton_v3.7.x\">FlagTree CPU</a> provides a CPU backend for Triton, allowing kernels written with Triton\u2019s Python API to compile and run on CPUs. Its compiler lowers Triton kernels through MLIR/LLVM into native CPU code, while its runtime handles CPU target selection, kernel launches, and compilation caching. This guide covers the Triton 3.7.2 implementation on Linux Arm64 and validates it with a vector-add kernel and FlagGems W4A8 operator tests.</p><p>Build and validate the Triton 3.7.2 CPU backend using the scripts in <a class=\"reference external\" href=\"https://github.com/flagos-ai/community/tree/main/fep/sig-edge/scripts/flagtree-cpu37\">flagos-ai/community</a>. Follow these steps in the same shell.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-amd.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab AMD <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/amd/\">amd</a><a class=\"headerlink\" href=\"#amd-amd\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-ascend.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huawei Ascend\uff08\u534e\u4e3a\u6607\u817e\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/blob/triton_v3.5.x/third_party/ascend\">ascend</a>3.5<a class=\"headerlink\" href=\"#huawei-ascend-ascend3-5\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (910B|910C)<a class=\"headerlink\" href=\"#use-the-image-910b-910c\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-tileir.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA TileIR <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tileir/\">tileir</a>3.6<a class=\"headerlink\" href=\"#nvidia-tileir-tileir3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (Hopper/Blackwell)<a class=\"headerlink\" href=\"#use-the-image-hopper-blackwell\" title=\"Link to this heading\">#</a></h3><p>This image can also be used for the <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia</span></code> backend.</p>", "a[href=\"#install-flagtree\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagTree<a class=\"headerlink\" href=\"#install-flagtree\" title=\"Link to this heading\">#</a></h1><h2>Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2><p>The best practice to avoid environment compatibility issues is to use the image recommended in the <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/wiki/User-Manual\">User Manual</a>.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-enflame.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Enflame\uff08\u71e7\u539f\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/enflame/\">enflame</a>3.6<a class=\"headerlink\" href=\"#enflame-enflame3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (GCU300|GCU400)<a class=\"headerlink\" href=\"#use-the-image-gcu300-gcu400\" title=\"Link to this heading\">#</a></h3><p>Tips: You can use <code class=\"docutils literal notranslate\"><span class=\"pre\">apt</span> <span class=\"pre\">install</span> <span class=\"pre\">aria2;</span> <span class=\"pre\">aria2c</span> <span class=\"pre\">-c</span> <span class=\"pre\">...</span></code> instead of <code class=\"docutils literal notranslate\"><span class=\"pre\">wget</span> <span class=\"pre\">...</span></code> to download large files with resume support.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-mthreads.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Moore Threads\uff08\u6469\u5c14\u7ebf\u7a0b\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/mthreads/\">mthreads</a>3.6<a class=\"headerlink\" href=\"#moore-threads-mthreads3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (Triton 3.6, MTT-S5000)<a class=\"headerlink\" href=\"#use-the-image-triton-3-6-mtt-s5000\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#option-3-install-wheel-package\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 3: Install wheel package<a class=\"headerlink\" href=\"#option-3-install-wheel-package\" title=\"Link to this heading\">#</a></h2><p>If you do not wish to build from source, you can directly pull and install whl (partial backend support).</p>", "a[href=\"install-arm64-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install on Arm64 CPU<a class=\"headerlink\" href=\"#install-on-arm64-cpu\" title=\"Link to this heading\">#</a></h1><p>Before installing the FlagTree on Arm64 CPU, please read the following notes:</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-rpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huixi Intelligence\uff08\u8f89\u7fb2\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/rpu/\">rpu</a>3.6<a class=\"headerlink\" href=\"#huixi-intelligence-rpu3-6\" title=\"Link to this heading\">#</a></h1><p>The <strong>Rhino RPU</strong> is the AI accelerator inside Huixi Intelligence\u2019s \u5149\u81f3 R1 SoC\n(<a class=\"reference external\" href=\"https://www.rhino.auto/\">rhino.auto</a>). Unlike the CPU/GPU backends, the RPU\nbackend has <strong>no preinstalled image and no CPU simulator</strong> \u2014 it compiles and\nruns only on a physical R1 SoC board, and its driver, runtime, and toolchain are\nobtained from the vendor. Build and test directly on the board.</p>", "a[href=\"#option-2-install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 2: Install from source<a class=\"headerlink\" href=\"#option-2-install-from-source\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from source, see the following list:</p>", "a[href=\"#option-1-install-from-prebuilt-docker-image\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 1: Install from prebuilt Docker image<a class=\"headerlink\" href=\"#option-1-install-from-prebuilt-docker-image\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from prebuilt Docker image, see the following list:</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-tsingmicro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Tsingmicro\uff08\u6e05\u5fae\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tsingmicro/\">tsingmicro</a>3.6<a class=\"headerlink\" href=\"#tsingmicro-tsingmicro3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (TX81)<a class=\"headerlink\" href=\"#use-the-image-tx81\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-sunrise.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Sunrise\uff08\u66e6\u671b\u82af\u79d1\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/sunrise/\">sunrise</a>3.6<a class=\"headerlink\" href=\"#sunrise-sunrise3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (S2)<a class=\"headerlink\" href=\"#use-the-image-s2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-ppu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab T-Head\uff08\u5e73\u5934\u54e5\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/ppu/\">ppu</a>3.6<a class=\"headerlink\" href=\"#t-head-ppu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (810E|890P)<a class=\"headerlink\" href=\"#use-the-image-810e-890p\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#running-tests\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Running tests<a class=\"headerlink\" href=\"#running-tests\" title=\"Link to this heading\">#</a></h2><p>After installation, you can generally run the following tests. For specific backend support tests, please refer to .github/workflow/${backend_name}-build-and-test.yml in the corresponding branch.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-aipu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ARM China\uff08\u5b89\u8c0b\u79d1\u6280\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.3.x/third_party/aipu/\">aipu</a>3.3<a class=\"headerlink\" href=\"#arm-china-aipu3-3\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (for the x64 CPU simulation environment)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-for-the-x64-cpu-simulation-environment\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later installation steps.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-nv.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/nvidia/\">nvidia</a><a class=\"headerlink\" href=\"#nvidia-nvidia\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-xpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab KLX <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/xpu/\">xpu</a>3.6<a class=\"headerlink\" href=\"#klx-xpu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (P800)<a class=\"headerlink\" href=\"#use-the-image-p800\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#environment-setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2><p>The best practice to avoid environment compatibility issues is to use the image recommended in the <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/wiki/User-Manual\">User Manual</a>.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-spacemit.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab SpacemiT\uff08\u8fdb\u8fed\u65f6\u7a7a\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/spacemit/\">spacemit</a>3.6<a class=\"headerlink\" href=\"#spacemit-spacemit3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (x64 emulation environment)<a class=\"headerlink\" href=\"#use-the-image-x64-emulation-environment\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-hcu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab HYGON\uff08\u6d77\u5149\u4fe1\u606f\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/hcu/\">hcu</a>3.6<a class=\"headerlink\" href=\"#hygon-hcu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (BW1000)<a class=\"headerlink\" href=\"#use-the-image-bw1000\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#q-a\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q&amp;A<a class=\"headerlink\" href=\"#q-a\" title=\"Link to this heading\">#</a></h2><p>Q: After installation, running the program reports: version GLIBC or GLIBCXX not found</p><p>A: Check which GLIBC / GLIBCXX versions are supported by libc.so.6 and libstdc++.so.6.0.30 in your environment:</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-iluvatar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ILUVATAR\uff08\u5929\u6570\u667a\u82af\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/iluvatar/\">iluvatar</a>3.6<a class=\"headerlink\" href=\"#iluvatar-iluvatar3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (BI-V150)<a class=\"headerlink\" href=\"#use-the-image-bi-v150\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
